 const renameTreeItem=async()=>{const item=renameItem;if(!item)return;let name=renameName.trim();if(!name||name==='.'||name==='..'||/[\\/]/.test(name))throw Error('Use a name without slashes.');if(item.kind==='file'&&!name.endsWith('.md'))name+='.md';const parent=item.path.split('/').slice(0,-1).join('/'),path=parent?parent+'/'+name:name;safePath.parse(path);if(path===item.path){setRenameItem(null);return;}await save();await item.source.sync();if(item.kind==='folder'){await item.source.request('/folders/rename',{method:'POST',body:JSON.stringify({path:item.path,name})},item.source.cache.identity?.csrf);}else{const current=item.source.cache.snapshot.notes.find(n=>n.id===item.id&&!n.deleted);if(!current||current.path!==item.path)throw Error('The file changed. Refresh before renaming.');if(item.source.cache.snapshot.notes.some(n=>n.id!==item.id&&!n.deleted&&n.path.toLowerCase()===path.toLowerCase()))throw Error('A file with that name already exists.');const opened=await item.source.openFile(current);await item.source.save({...opened,path});}await item.source.sync();if(item.source===engine&&draft.current){const updated=item.source.cache.snapshot.notes.find(n=>n.id===draft.current!.id);if(updated){draft.current=updated;setSelected(updated);}}setRenameItem(null);render(n=>n+1);};
