 const restore=async(n:Note,rev:number)=>{await save();if(!engine.manualLocal)await engine.sync();if(engine.cache.outbox.some(m=>m.id===n.id))throw new Error('Sync pending edits before restoring this file.');const current=engine.cache.snapshot.notes.find(x=>x.id===n.id);if(!current)throw new Error('File no longer exists on server');const result:Note=await api('/restore/'+n.id,{method:'POST',body:JSON.stringify({base:current.rev,rev:Math.min(rev,current.rev),op:crypto.randomUUID()})},identity?.csrf);draft.current=result;setSelected(result);await engine.sync();};
