 const resolveConflict=async(c:Conflict,action:'keep-server'|'keep-device'|'keep-both'|'merge',mergedContent?:string)=>{const choice:{action:'keep-server'|'keep-device'|'keep-both'|'merge';expectedServerRevision:number;path?:string;content?:string}={action,expectedServerRevision:engine.cache.snapshot.notes.find(n=>n.id===c.mutation.id)?.rev??c.current};if(action==='keep-both')choice.path=c.mutation.path.replace(/\.md$/,` (device conflict ${c.id.slice(0,8)}).md`);if(action==='merge'){if(mergedContent===undefined)throw new Error('Enter the merged file content first.');choice.content=mergedContent;}const current=draft.current,v=version.current,wasDirty=dirtyRef.current;await engine.resolveConflict(c.id,choice);if(current?.id===c.mutation.id&&draft.current?.id===current.id&&version.current===v){const resolved=engine.cache.snapshot.notes.find(n=>n.id===current.id);if(resolved){if(!wasDirty||(current.content===c.mutation.content&&current.path===c.mutation.path)){draft.current=resolved;setSelected(resolved);dirtyRef.current=false;setDirty(false);version.current++;}else{draft.current={...current,rev:resolved.rev};setSelected(draft.current);}}}};
