 const updateCollectionNote=async(noteId:string,change:(note:Note)=>Note)=>{if(!await beforeLeave())return;const found=engine.cache.snapshot.notes.find(item=>item.id===noteId&&!item.deleted);if(!found)throw new Error('That source file is no longer available.');const note:Note=await engine.openFile(found);const changed=change(note);await engine.save(changed);if(!engine.manualLocal)await engine.sync();const updated=engine.cache.snapshot.notes.find(item=>item.id===noteId)??changed;if(draft.current?.id===noteId){draft.current=updated;setSelected(updated);}render(value=>value+1);};
