 const loadOrdinaryTaskNotes=async()=>{const loaded:Note[]=[];for(const listed of engine.cache.snapshot.notes){if(!listed.deleted&&isOrdinaryPath(listed.path))loaded.push(await engine.openFile(listed));}return loaded;};
